func getUserByNameWithTypes(ctx context.Context, name string, types ...UserType) (*User, error) {
	u := &User{}
	sess := db.GetEngine(ctx).Where(builder.Eq{"lower_name": strings.ToLower(name)})
	if len(types) > 0 {
		sess.In("`type`", types)
	}
	has, err := sess.Get(u)
	if err != nil {
		return nil, err
	} else if !has {
		return nil, ErrUserNotExist{Name: name}
	}
	return u, nil
}

